function calculateBill(){
 const total=document.getElementById('total').valueAsNumber;
 const tip=document.getElementById('tip').valueAsNumber;
 const people=document.getElementById('people').valueAsNumber;
 const output=document.getElementById('result'),problem=document.getElementById('problem');
 if(![total,tip,people].every(Number.isFinite)||total<0||total>1000000||tip<0||tip>100||people<1||people>1000||!Number.isInteger(people)){output.textContent='';problem.textContent='Introduce un total válido, una propina de 0 a 100 y un número entero de personas mayor que cero.';return null;}
 const amount=total*(1+tip/100)/people;problem.textContent='';output.textContent=amount.toLocaleString('es-ES',{style:'currency',currency:'EUR'})+' por persona';return {total,tip,people,amount};
}
function resetBill(){document.getElementById('total').value=20;document.getElementById('tip').value=0;document.getElementById('people').value=2;calculateBill();}
async function askBill(){const values=calculateBill();if(!values)return;try{await Websandbox.connection.remote.sendPrompt({text:'Explícame este reparto de cuenta en euros: '+JSON.stringify(values)});}catch(e){document.getElementById('problem').textContent='No se pudo preparar la consulta.';}}
